head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — initPageSize, search 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        dma_SearchReq.set("integUsrId",$c.session.getUserInfo("integUsrId"));
        scwin.initPageSize();
        scwin.search(true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52000.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name sel_size_onviewchange
 * @description 페이지 사이즈 변경
 * @param {Object} info 이벤트 정보 객체
 * @returns {void}
 * @hidden N
 */
scwin.sel_size_onviewchange = function (info) {
    try {
        scwin.search(false);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52000.sel_size_onviewchange" });
    }
};

/**
 * @method
 * @name pageList1_onclick
 * @description 페이지네이션 현재 페이지 변경
 * @param {Number} index 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.pageList1_onclick = function (index) {
    try {
        dma_SearchReq.set("page", index);// 현재페이지
        scwin.search(false);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52000.pageList1_onclick" });
    }
};

/**
 * @method
 * @name grd_list_oncellclick
 * @description 컬럼 클릭 이벤트 (회사명, 상태, 비고 세팅)
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_list_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        let prtdepoNo = dlt_prtdepoDisposalRes.getCellData(rowIndex, "prtdepoNo");
        let lstApprovYn = dlt_prtdepoDisposalRes.getCellData(rowIndex, "lstApprovYn");
        let listProcsStatCd = dlt_prtdepoDisposalRes.getCellData(rowIndex, "listProcsStatCd");

        // 회사명
        if (columnId === "comNm") {
            scwin.viewDetail(prtdepoNo, lstApprovYn, listProcsStatCd);
        }

        // 상태
        if (columnId === "lstApprovYn_custom1" ) {    // 상태컬럼
            if(lstApprovYn === "0" && (listProcsStatCd ==="" || listProcsStatCd === "35" )) {
                scwin.viewDetail(prtdepoNo, lstApprovYn, listProcsStatCd);
            } else if (lstApprovYn === "3" && listProcsStatCd === "35" ) {
                scwin.viewDetail(prtdepoNo, lstApprovYn, listProcsStatCd);
            } else if ((lstApprovYn === "0" || listProcsStatCd === "7") && listProcsStatCd === "37") {
                scwin.viewDetail(prtdepoNo, lstApprovYn, listProcsStatCd);
            } else if (lstApprovYn === "7" && listProcsStatCd === "38" ) {
                scwin.viewDetail(prtdepoNo, lstApprovYn, listProcsStatCd);
            }  else {
                scwin.viewDetail(prtdepoNo, lstApprovYn, listProcsStatCd);
            }
        }

        // 비고
        if (columnId === "lstApprovYn_custom2" ) {    // 상태컬럼
            if(lstApprovYn === "0" && listProcsStatCd === "") {
                scwin.sendPrtDepoWithd(prtdepoNo, '2');
            } else if ((lstApprovYn === "0" || lstApprovYn === "3") && listProcsStatCd === "35") {
                scwin.sendPrtDepoWithd(prtdepoNo, '3');
            } else if ((lstApprovYn === "0" || listProcsStatCd === "7") && listProcsStatCd === "37") {
                scwin.sendPrtDepoWithd(prtdepoNo, '3');
            } else if (lstApprovYn === "7" && listProcsStatCd === "38" ) {
                scwin.sendPrtDepoWithd(prtdepoNo, '3');
            } else if (lstApprovYn === "3" && (listProcsStatCd === "33" || listProcsStatCd === "36" || listProcsStatCd === "37")) {
                scwin.openAdjReqPop(prtdepoNo, '150');
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52000.grd_list_oncellclick" });
    }
};

/**
 * @method
 * @name write_onclick
 * @description 「신규작성」 버튼 클릭 — 작성 화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.write_onclick = function (e) {
    try {
        const data = {
            searchType: "0",
        };
        const opts = {
            id: "ULDFIL52100",
            popupName: "의무보유주식의 처분-작성화면",
            width: 900,
            height: 600,
            frameModal: "top",
            type: "pageFramePopup",
        };
        // $c.win.openPopup("/ui/lst/lstinvstg/ULDFIL52100.xml", opts, data);
        $c.win.moveUrl("/ui/lst/lstinvstg/ULDFIL52100.xml", data);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52000.write_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 의무보유주식 처분 목록을 페이징 조회한다.
 * @param {Boolean} isFirst 최초 조회 여부
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function (isFirst) {

    if(isFirst) {
        dma_SearchReq.set("page", 1);// 현재페이지 초기화
        dma_SearchReq.set("size", 10);// 페이지당 데이터 개수
    }

    const sbmOptions = {
        id : "sbm_prtdepoDisposa",
        method: "get",
        action : "/api/listing/listinvstg/prtdepo-disposal/select-list-paging",
        ref : "dma_SearchReq",
        target : "dma_SearchRes=body,dlt_prtdepoDisposalRes=body.content",
        gridview : "grd_list",
        isProcessMsg : false
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);

    if (res.responseJSON.success === true) {
        const prtdepoDisposalList = dlt_prtdepoDisposalRes.getAllJSON();

        if(!prtdepoDisposalList || prtdepoDisposalList.length === 0) {
            dma_SearchRes.set("page", 0);

        }
        if (isFirst) {
            // 페이지네이션 생성
            pageList1.setCount(dma_SearchRes.get("totalPages"));
        } else {
            // 페이지네이션 선택
            pageList1.setSelectedIndex(dma_SearchRes.get("page"));
        }
    }
};

/**
 * @method
 * @name sendPrtDepoWithd
 * @description 의무보유주식 처분 신청을 제출한다.
 * @param {String} prtDepoNo 식별자
 * @param {String} updateType 구분 코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.sendPrtDepoWithd = async function (prtDepoNo, updateType) {

    let res = await $c.win.confirm($c.data.getMessage("com_crud_0198", "제출"));
    if(res){
        dma_submitReq.set("bzProcsNo", prtDepoNo); // 업무처리번호
        dma_submitReq.set("prtDepoNo", prtDepoNo); // 업무처리번호
        dma_submitReq.set("searchType", updateType); // 0:최초입력, 1:해당기업조회, 2:입력후저장내용 불러오기, 3:수정, 4:첨부파일, 5:최종승인 , 6:최종승인 반려
        dma_submitReq.set("regId", $c.session.getUserInfo("integUsrId")); // 등록자ID
        const sbmOptions = {
            id : "sbm_submit",
            method: "post",
            action : "/api/listing/listinvstg/prtdepo-disposal/submit",
            ref : "dma_submitReq",
            // target : "dma_submitRes=body",
            // gridview : "grd_list",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        await scwin.sbm_submit_submitdone(sbmRtn);
        }
};

/**
 * @method
 * @name sbm_submit_submitdone
 * @description 제출 통신 응답 후처리 — 결과 메시지 표시 후 목록을 재조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_submit_submitdone = function(e) {
    $c.win.alert($c.data.getMessage("com_complete_0150", "제출"));
    scwin.search(true);
}

/**
 * @method
 * @name popupCallback
 * @description 수정요청 팝업을 열고 닫힌 뒤 목록을 재조회한다.이 닫힌 뒤 목록을 재조회한다.
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function(){
    scwin.search(false);
}

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPageSize
 * @description 페이지 크기 셀렉트박스(sel_size)에 15/30/50/100 항목을 채운다.
 * @returns {void}
 * @hidden N
 */
scwin.initPageSize = function () {
    const sel_size = $p.getComponentById("sel_size");
    if (!sel_size) {
        return;
    }
    $c.data.comboCbDataSetDynamic(sel_size, [15, 30, 50, 100], 0);
};

/**
 * @method
 * @name setStatNm
 * @description 그리드 상태 컬럼 커스텀 포매터 — 승인여부·처리상태에 따라 작성중/수정가능 등 버튼 HTML 을 만든다.
 * @param {*} data 셀 값(원본 데이터)
 * @param {String} formattedData 표시 형식 문자열
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {String} 셀에 표시할 HTML
 * @hidden N
 */
scwin.setStatNm = function (data, formattedData, rowIndex, columnIndex) {
    let lstApprovYn = dlt_prtdepoDisposalRes.getCellData(rowIndex, "lstApprovYn");
    let listProcsStatCd = dlt_prtdepoDisposalRes.getCellData(rowIndex, "listProcsStatCd");
    let lstApprovNm     = dlt_prtdepoDisposalRes.getCellData(rowIndex, "lstApprovNm");

    if (columnIndex === 5 ) {    // 상태컬럼
        if(lstApprovYn === "0" && (listProcsStatCd ==="" || listProcsStatCd === "35" )) {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom1", "작성중");
            data = "<button>작성중</button>";
        } else if (lstApprovYn === "3" && listProcsStatCd === "35" ) {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom1", "수정가능");
            data = "<button>수정가능</button>";
        } else if ((lstApprovYn === "0" || listProcsStatCd === "7") && listProcsStatCd === "37") {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom1", "재작성");
            data = "<button>재작성</button>";
        } else if (lstApprovYn === "7" && listProcsStatCd === "38" ) {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom1", "재작성");
            data = "<button>재작성</button>";
        }  else {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom1", lstApprovNm);
        }
    }

    return data;
};

/**
 * @method
 * @name setPrtdepoNm
 * @description 그리드 비고 컬럼 커스텀 포매터 — 승인여부·처리상태에 따라 제출 버튼 HTML 을 만든다.
 * @param {*} data 셀 값(원본 데이터)
 * @param {String} formattedData 표시 형식 문자열
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {String} 셀에 표시할 HTML
 * @hidden N
 */
scwin.setPrtdepoNm = function (data, formattedData, rowIndex, columnIndex) {
    let lstApprovYn = dlt_prtdepoDisposalRes.getCellData(rowIndex, "lstApprovYn");
    let listProcsStatCd = dlt_prtdepoDisposalRes.getCellData(rowIndex, "listProcsStatCd");

    if (columnIndex === 6 ) {    // 상태컬럼
        if(lstApprovYn === "0" && listProcsStatCd === "") {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom2", "제출");
            data = "<button style='color: #ff0000; border-color: red;'>제출</button>";
        } else if ((lstApprovYn === "0" || lstApprovYn === "3") && listProcsStatCd === "35") {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom2", "제출");
            data = "<button style='color: #ff0000; border-color: red;'>제출</button>";
        } else if ((lstApprovYn === "0" || listProcsStatCd === "7") && listProcsStatCd === "37") {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom2", "제출");
            data = "<button style='color: #ff0000; border-color: red;'>제출</button>";
        } else if (lstApprovYn === "7" && listProcsStatCd === "38" ) {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom2", "제출");
            data = "<button style='color: #ff0000; border-color: red;'>제출</button>";
        } else if (lstApprovYn === "3" && (listProcsStatCd === "33" || listProcsStatCd === "36" || listProcsStatCd === "37")) {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom2", "수정요청");
            data = "<button>수정요청</button>";
        } else {
            dlt_prtdepoDisposalRes.setCellData(rowIndex, "lstApprovYn_custom2", "-");
        }
    }

    return data;
};

/**
 * @method
 * @name viewDetail
 * @description 상세내용 조회 팝업 searchType 0:최초입력, 1:해당기업조회, 2:입력후저장내용 불러오기, 3:수정, 4:첨부파일, 5:최종승인 , 6:최종승인 반려
 * @param {String} prtdepoNo 식별자
 * @param {String} approvYn 구분 코드
 * @param {String} procsStatCd 구분 코드
 * @returns {void}
 * @hidden N
 */
scwin.viewDetail = function (prtdepoNo, approvYn, procsStatCd) {

    if(approvYn === '0' || approvYn === '7'){// 작성중
        if(procsStatCd === '38')// 첨부파일 제출완료
            searchType = '5';
        else
            searchType = '2';
    }
    else if(approvYn === '2'){// 제출완료 - 수정불가능
        if(procsStatCd === '38')// 첨부파일 제출완료
            searchType = '5';
        else
            searchType = '1';
    }
    else if(approvYn === '3'){ // 접수완료 - 수정가능
        if(procsStatCd === '34')// 수정요청
            searchType = '1';
        else if(procsStatCd === '35')// 수정승인 - 수정가능
            searchType = '3';
        else  // 수정불가 - 항목수정불가, 첨부만 가능
            searchType = '1';
    }
    else if(approvYn === '8'){// 처분승인 - 수정불가능, 처분승인공문을 다운, 재의무보유첨부만 할 수 있다.
        searchType = '4';
    }
    else if(approvYn === '9'){// 최종승인 - 모두 불가능
        searchType = '5';
    }

    let screenId = "";
    if (searchType === "1" || searchType === "4" || searchType === "5") {
        screenId = "ULDFIL52101";
    } else {
        screenId = "ULDFIL52100";
    }

    const data = {
        prtDepoNo: prtdepoNo, // 의무보유주식의 처분 업무처리번호
        searchType: searchType,
    };
    const opts = {
        id: screenId,
        popupName: "의무보유주식의 처분-상세내용",
        width: 900,
        height: 700,
        frameModal: "top",
        type: "pageFramePopup",
    };
    // $c.win.openPopup("/ui/lst/lstinvstg/ULDFIL52101.xml", opts, data);
    $c.win.moveUrl("/ui/lst/lstinvstg/" + screenId + ".xml", data);
};

/**
 * @method
 * @name openAdjReqPop
 * @description 수정요청 팝업
 * @param {String} prtdepoNo 식별자
 * @param {String} listInvstgBzTpCd 구분 코드
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.openAdjReqPop = async function(prtdepoNo, listInvstgBzTpCd) {
    const data = {
        bzProcsNo : prtdepoNo,
        listInvstgBzTpCd : listInvstgBzTpCd,
        listBzDtlTpCd : "51", // TODO: DB확인해보니 (23: 의무보유) 인듯한데 확인필요
        callbackFn: "scwin.popupCallback",
    };

    const options = {
        id: "ULDFIL59411",
        popupName: "상장공시제출시스템 수정요청",
        width: 900,
        height: 380,
        frameModal: "top"
    };

    const result = await $c.win.openPopup("/ui/lst/common/ULDFIL59411.xml", options, data);
}
